package com.bank.unpersist.cache;

// One cached dataset's storage facts (mirrors a Storage tab row).
public class CacheEntry {
    public final String name;
    public final int totalPartitions;
    public int cachedPartitions;
    public long memoryBytes;
    public long diskBytes;

    public CacheEntry(String name, int totalPartitions) {
        this.name = name;
        this.totalPartitions = totalPartitions;
    }
    public double fractionCached() {
        return totalPartitions == 0 ? 0 : (double) cachedPartitions / totalPartitions;
    }
}
