package com.bank.unpersist.cache;

import java.util.*;
import java.util.logging.Logger;

// Caches datasets into a bounded store; unpersist frees them promptly.
public class CacheManager {
    private static final Logger log = Logger.getLogger(CacheManager.class.getName());
    private final long capacityBytes;
    private long usedBytes = 0;
    private final Map<String, CacheEntry> cache = new LinkedHashMap<>();

    public CacheManager(long capacityBytes) { this.capacityBytes = capacityBytes; }

    // Cache a dataset; spill to disk if memory is short (memory-and-disk behavior).
    public void cache(String name, int partitions, long sizeBytes) {
        CacheEntry e = new CacheEntry(name, partitions);
        long perPart = sizeBytes / partitions;
        for (int i = 0; i < partitions; i++) {
            if (usedBytes + perPart <= capacityBytes) {
                usedBytes += perPart;
                e.memoryBytes += perPart;
            } else {
                e.diskBytes += perPart; // spill
            }
            e.cachedPartitions++;
        }
        cache.put(name, e);
        log.info(() -> "cached '" + name + "': " + e.cachedPartitions + "/" + partitions
                + " partitions, mem=" + e.memoryBytes + "B, disk=" + e.diskBytes + "B");
    }

    // unpersist: EAGERLY free all blocks for this dataset.
    public void unpersist(String name) {
        CacheEntry e = cache.remove(name);
        if (e != null) {
            usedBytes -= e.memoryBytes;
            log.info(() -> "unpersist '" + name + "': freed " + e.memoryBytes
                    + "B memory (storage released)");
        }
    }

    // Mirror of the Spark UI Storage tab.
    public void storageReport() {
        log.info("── Storage tab ──");
        for (CacheEntry e : cache.values()) {
            log.info(() -> "  " + e.name + ": cached " + (int) (e.fractionCached() * 100)
                    + "% (" + e.cachedPartitions + "/" + e.totalPartitions
                    + "), mem=" + e.memoryBytes + "B, disk=" + e.diskBytes + "B");
        }
        log.info(() -> "  TOTAL memory used = " + usedBytes + "B of " + capacityBytes + "B");
    }
}
