package com.bank.unpersist;

import com.bank.unpersist.cache.CacheManager;
import java.util.logging.*;

public class UnpersistDemo {
    private static final Logger log = Logger.getLogger(UnpersistDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new UnpersistLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        CacheManager cm = new CacheManager(100_000_000L); // 100 MB

        // Phase 1: cache cleaned transactions for the daily reports.
        log.info("=== Phase 1: daily reports ===");
        cm.cache("cleaned_txns", 4, 60_000_000);
        cm.storageReport();

        // Reports done → free it before the next phase (long-running discipline).
        cm.unpersist("cleaned_txns");

        // Phase 2: cache ML features (would not fit alongside phase 1 if not freed).
        log.info("=== Phase 2: ML training ===");
        cm.cache("ml_features", 4, 80_000_000);
        cm.storageReport();

        cm.unpersist("ml_features");
        log.info("=== End: storage released ===");
        cm.storageReport();
    }
}

